//! Footprints of the ordinary towns around 1340 (`data/map/towns_1340.json`, generated by
//! `cent-ans geo towns`; ADR 0036): enclosure polygon (radii at regular bearings), gates,
//! suburbs, monuments, river, bridge, plus the plan and wall rules. Port of `town_data.gd`.
//! Local coordinates are metres from the anchor (x east = +X world, y south = +Z world).

use std::collections::HashMap;
use std::path::Path;

use bevy::math::Vec2;
use serde_json::Value;

#[derive(Debug, Clone, PartialEq)]
pub struct Gate {
    pub bearing: f32,
    /// `main` or `track`.
    pub kind: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Faubourg {
    pub bearing: f32,
    pub start_m: f32,
    pub length_m: f32,
}

#[derive(Debug, Clone, PartialEq)]
pub struct MonumentSpec {
    pub kind: String,
    pub at: Vec2,
    pub size_m: f32,
    pub yaw: f32,
    pub keep: bool,
}

#[derive(Debug, Clone, PartialEq)]
pub struct River {
    pub line: Vec<Vec2>,
    pub width_m: f32,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Bridge {
    pub at: Vec2,
    pub dir: Vec2,
    pub width_m: f32,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Town {
    pub id: String,
    /// `city`, `town`, `village`, `castle` or `abbey`.
    pub kind: String,
    pub seed: u32,
    pub population: u32,
    pub households: u32,
    pub core_population: u32,
    /// `none`, `palisade` or `stone`.
    pub walls: String,
    pub radii: Vec<f32>,
    pub gates: Vec<Gate>,
    pub faubourgs: Vec<Faubourg>,
    pub monuments: Vec<MonumentSpec>,
    pub parishes: u32,
    pub river: Option<River>,
    pub bridge: Option<Bridge>,
    /// Anchor in map units.
    pub px: Vec2,
}

impl Town {
    pub fn is_village(&self) -> bool {
        matches!(self.kind.as_str(), "village" | "castle" | "abbey")
    }

    /// Distance (map units) beyond which nothing of the town stands.
    pub fn extent_units(&self, meters_per_unit: f32) -> f32 {
        let mut reach = self.radii.iter().copied().fold(0.0_f32, f32::max);
        for f in &self.faubourgs {
            reach = reach.max(f.start_m + f.length_m);
        }
        (reach + 160.0) / meters_per_unit
    }
}

/// `walls.<kind>` of the rules.
#[derive(Debug, Clone, PartialEq, Default)]
pub struct WallSpec {
    pub height_m: f32,
    pub thickness_m: f32,
    pub tower_spacing_m: f32,
    pub tower_radius_m: f32,
    pub tower_height_m: f32,
}

/// `plan` section: street widths, parcel sizes, house mixes.
#[derive(Debug, Clone, PartialEq)]
pub struct PlanParams {
    pub frontage_m: [f32; 2],
    pub depth_m: [f32; 2],
    pub faubourg_frontage_m: [f32; 2],
    pub faubourg_depth_m: [f32; 2],
    pub village_frontage_m: [f32; 2],
    pub street_main: f32,
    pub street_secondary: f32,
    pub street_ring: f32,
    pub street_lane: f32,
    pub secondary_spacing_m: [f32; 2],
    pub lane_spacing_m: [f32; 2],
    pub households_intra: f32,
    pub households_faubourg: f32,
    pub households_village: f32,
    pub market_area_per_inhabitant: f32,
    pub market_min_m: [f32; 2],
    /// Zone key (`intra`, `faubourg`, `village`) -> (house kind, weight).
    pub house_kinds: HashMap<String, Vec<(String, f32)>>,
}

impl Default for PlanParams {
    fn default() -> Self {
        Self {
            frontage_m: [5.0, 8.0],
            depth_m: [20.0, 40.0],
            faubourg_frontage_m: [8.0, 16.0],
            faubourg_depth_m: [30.0, 60.0],
            village_frontage_m: [14.0, 26.0],
            street_main: 8.0,
            street_secondary: 5.0,
            street_ring: 5.0,
            street_lane: 3.0,
            secondary_spacing_m: [70.0, 110.0],
            lane_spacing_m: [60.0, 95.0],
            households_intra: 1.0,
            households_faubourg: 1.0,
            households_village: 1.0,
            market_area_per_inhabitant: 0.4,
            market_min_m: [30.0, 40.0],
            house_kinds: HashMap::new(),
        }
    }
}

/// Growth rules (`data/map/building_models.json` `growth`, ADR 0162).
#[derive(Debug, Clone, PartialEq)]
pub struct GrowthConfig {
    pub population_step: f32,
    pub max_quarters: u32,
    pub houses_per_quarter: u32,
    pub frontage_m: f32,
    pub setback_m: f32,
    pub gap_m: f32,
    pub house_models: Vec<String>,
    pub enclosure_margin_m: f32,
    pub enclosure_sink_m: f32,
    pub gate_height_m: f32,
    /// (`palisade` | `stone`, building ids that give it).
    pub enclosure_kinds: Vec<(String, Vec<String>)>,
}

impl Default for GrowthConfig {
    fn default() -> Self {
        Self {
            population_step: 0.08,
            max_quarters: 6,
            houses_per_quarter: 14,
            frontage_m: 16.0,
            setback_m: 10.0,
            gap_m: 40.0,
            house_models: Vec::new(),
            enclosure_margin_m: 35.0,
            enclosure_sink_m: 3.0,
            gate_height_m: 16.0,
            enclosure_kinds: Vec::new(),
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct TownDb {
    pub meters_per_unit: f32,
    pub towns: HashMap<String, Town>,
    pub plan: PlanParams,
    pub walls: HashMap<String, WallSpec>,
    pub gate_depth_m: f32,
    pub growth: GrowthConfig,
}

fn v2(v: &Value) -> Vec2 {
    Vec2::new(
        v[0].as_f64().unwrap_or(0.0) as f32,
        v[1].as_f64().unwrap_or(0.0) as f32,
    )
}

fn pair(v: &Value, default: [f32; 2]) -> [f32; 2] {
    match (v[0].as_f64(), v[1].as_f64()) {
        (Some(a), Some(b)) => [a as f32, b as f32],
        _ => default,
    }
}

fn num(v: &Value, default: f32) -> f32 {
    v.as_f64().map_or(default, |x| x as f32)
}

impl TownDb {
    pub fn load(data_dir: &Path) -> TownDb {
        let read = |rel: &str| -> Value {
            std::fs::read_to_string(data_dir.join(rel))
                .ok()
                .and_then(|t| serde_json::from_str(&t).ok())
                .unwrap_or(Value::Null)
        };
        TownDb::from_json(
            &read("map/towns_1340.json"),
            &read("map/building_models.json"),
        )
    }

    pub fn from_json(towns_doc: &Value, models_doc: &Value) -> TownDb {
        let d = PlanParams::default();
        let p = &towns_doc["plan"];
        let mut house_kinds = HashMap::new();
        if let Some(zones) = p["house_kinds"].as_object() {
            for (zone, mix) in zones {
                let mut entries: Vec<(String, f32)> = mix
                    .as_object()
                    .map(|m| m.iter().map(|(k, w)| (k.clone(), num(w, 0.0))).collect())
                    .unwrap_or_default();
                entries.sort_by(|a, b| a.0.cmp(&b.0));
                house_kinds.insert(zone.clone(), entries);
            }
        }
        let plan = PlanParams {
            frontage_m: pair(&p["frontage_m"], d.frontage_m),
            depth_m: pair(&p["depth_m"], d.depth_m),
            faubourg_frontage_m: pair(&p["faubourg_frontage_m"], d.faubourg_frontage_m),
            faubourg_depth_m: pair(&p["faubourg_depth_m"], d.faubourg_depth_m),
            village_frontage_m: pair(&p["village_frontage_m"], d.village_frontage_m),
            street_main: num(&p["street_width_m"]["main"], d.street_main),
            street_secondary: num(&p["street_width_m"]["secondary"], d.street_secondary),
            street_ring: num(&p["street_width_m"]["ring"], d.street_ring),
            street_lane: num(&p["street_width_m"]["lane"], d.street_lane),
            secondary_spacing_m: pair(&p["secondary_spacing_m"], d.secondary_spacing_m),
            lane_spacing_m: pair(&p["lane_spacing_m"], d.lane_spacing_m),
            households_intra: num(&p["households_per_house"]["intra"], 1.0),
            households_faubourg: num(&p["households_per_house"]["faubourg"], 1.0),
            households_village: num(&p["households_per_house"]["village"], 1.0),
            market_area_per_inhabitant: num(&p["market_area_m2_per_inhabitant"], 0.4),
            market_min_m: pair(&p["market_min_m"], d.market_min_m),
            house_kinds,
        };
        let mut walls = HashMap::new();
        if let Some(w) = towns_doc["walls"].as_object() {
            for (kind, s) in w {
                if s.is_object() {
                    walls.insert(
                        kind.clone(),
                        WallSpec {
                            height_m: num(&s["height_m"], 8.0),
                            thickness_m: num(&s["thickness_m"], 2.0),
                            tower_spacing_m: num(&s["tower_spacing_m"], 0.0),
                            tower_radius_m: num(&s["tower_radius_m"], 0.0),
                            tower_height_m: num(&s["tower_height_m"], 0.0),
                        },
                    );
                }
            }
        }
        let mut towns = HashMap::new();
        if let Some(map) = towns_doc["towns"].as_object() {
            for (id, t) in map {
                if let Some(town) = parse_town(id, t) {
                    towns.insert(id.clone(), town);
                }
            }
        }
        TownDb {
            meters_per_unit: num(&towns_doc["meters_per_unit"], 719.0),
            towns,
            plan,
            walls,
            gate_depth_m: num(&towns_doc["walls"]["gate_depth_m"], 12.0),
            growth: parse_growth(&models_doc["growth"]),
        }
    }

    pub fn wall_spec(&self, kind: &str) -> WallSpec {
        self.walls.get(kind).cloned().unwrap_or(WallSpec {
            height_m: 8.0,
            thickness_m: 2.0,
            ..Default::default()
        })
    }
}

fn parse_growth(g: &Value) -> GrowthConfig {
    let d = GrowthConfig::default();
    let s = &g["suburbs"];
    let e = &g["enclosure"];
    GrowthConfig {
        population_step: num(&s["population_step"], d.population_step),
        max_quarters: s["max_quarters"].as_u64().unwrap_or(d.max_quarters as u64) as u32,
        houses_per_quarter: s["houses_per_quarter"]
            .as_u64()
            .unwrap_or(d.houses_per_quarter as u64) as u32,
        frontage_m: num(&s["frontage_m"], d.frontage_m),
        setback_m: num(&s["setback_m"], d.setback_m),
        gap_m: num(&s["gap_m"], d.gap_m),
        house_models: s["house_models"]
            .as_array()
            .map(|a| {
                a.iter()
                    .filter_map(|m| m.as_str().map(String::from))
                    .collect()
            })
            .unwrap_or_default(),
        enclosure_margin_m: num(&e["margin_m"], d.enclosure_margin_m),
        enclosure_sink_m: num(&e["sink_m"], d.enclosure_sink_m),
        gate_height_m: num(&e["gate_height_m"], d.gate_height_m),
        enclosure_kinds: e["kinds"]
            .as_array()
            .map(|a| {
                a.iter()
                    .filter_map(|k| {
                        Some((
                            k["kind"].as_str()?.to_string(),
                            k["buildings"]
                                .as_array()?
                                .iter()
                                .filter_map(|b| b.as_str().map(String::from))
                                .collect(),
                        ))
                    })
                    .collect()
            })
            .unwrap_or_default(),
    }
}

fn parse_town(id: &str, t: &Value) -> Option<Town> {
    let radii: Vec<f32> = t["radii"]
        .as_array()?
        .iter()
        .map(|r| num(r, 60.0))
        .collect();
    Some(Town {
        id: t["id"].as_str().unwrap_or(id).to_string(),
        kind: t["kind"].as_str().unwrap_or("town").to_string(),
        seed: t["seed"].as_u64().unwrap_or(1) as u32,
        population: t["population"].as_u64().unwrap_or(500) as u32,
        households: t["households"].as_u64().unwrap_or(100) as u32,
        core_population: t["core_population"]
            .as_u64()
            .or(t["population"].as_u64())
            .unwrap_or(500) as u32,
        walls: t["walls"].as_str().unwrap_or("none").to_string(),
        radii,
        gates: t["gates"]
            .as_array()
            .map(|a| {
                a.iter()
                    .map(|g| Gate {
                        bearing: num(&g["bearing"], 0.0),
                        kind: g["type"].as_str().unwrap_or("track").to_string(),
                    })
                    .collect()
            })
            .unwrap_or_default(),
        faubourgs: t["faubourgs"]
            .as_array()
            .map(|a| {
                a.iter()
                    .map(|f| Faubourg {
                        bearing: num(&f["bearing"], 0.0),
                        start_m: num(&f["start_m"], 0.0),
                        length_m: num(&f["length_m"], 0.0),
                    })
                    .collect()
            })
            .unwrap_or_default(),
        monuments: t["monuments"]
            .as_array()
            .map(|a| {
                a.iter()
                    .map(|m| MonumentSpec {
                        kind: m["kind"].as_str().unwrap_or("hall").to_string(),
                        at: v2(&m["at"]),
                        size_m: num(&m["size_m"], 20.0),
                        yaw: num(&m["yaw"], 0.0),
                        keep: m["keep"].as_bool().unwrap_or(false),
                    })
                    .collect()
            })
            .unwrap_or_default(),
        parishes: t["parishes"].as_u64().unwrap_or(0) as u32,
        river: t["river"].is_object().then(|| River {
            line: t["river"]["line"]
                .as_array()
                .map(|l| l.iter().map(v2).collect())
                .unwrap_or_default(),
            width_m: num(&t["river"]["width_m"], 20.0),
        }),
        bridge: t["bridge"].is_object().then(|| Bridge {
            at: v2(&t["bridge"]["at"]),
            dir: v2(&t["bridge"]["dir"]),
            width_m: num(&t["bridge"]["width_m"], 20.0),
        }),
        px: v2(&t["px"]),
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn real_data_loads() {
        let root = crate::paths::find_root().unwrap();
        let db = TownDb::load(&crate::paths::data_dir(&root));
        assert!(db.towns.len() > 1500, "{}", db.towns.len());
        assert!((db.meters_per_unit - 718.9766).abs() < 0.01);
        assert!(db.plan.house_kinds.contains_key("intra"));
        assert!(db.walls.contains_key("stone"));
        assert!(!db.growth.house_models.is_empty());
        let t = &db.towns["set_abbeville"];
        assert!(t.river.is_some() && t.bridge.is_some());
        assert!(t.radii.len() >= 3);
    }
}
